     has_lora = any(\"lora\" in k.lower() for k in f.keys())\n    except Exception:\n        pass\n\n    if has_lora:\n        logging.info(\"Detected manual LoRA checkpoint, injecting LoRA before loading\")\n        policy = _load_policy_with_lora(args, config)\n    else:\n        policy = _policy_config.create_trained_policy(\n            config, args.checkpoint, default_prompt=None\n        )\n    return policy\n\n\ndef _load_policy_with_lora(args, config):\n    \"\"\"Load policy from a checkpoint saved with manual LoRA injection.\"\"\"\n    import safetensors.torch as _sft\n    from openpi.policies import policy as _policy\n    from openpi.training import checkpoints as _checkpoints\n    from openpi.models import pi0_pytorch\n    import openpi.transforms as _transforms\n    from colliforce.lora_utils import inject_lora_pi0\n\n    device = \"cuda:{}\".format(args.gpu) if torch.cuda.is_available() else \"cpu\"\n\n    model = pi0_pytorch.PI0Pytorch(config=config.model)\n    inject_lora_pi0(model, pali_rank=16, pali_alpha=16.0,\n                    expert_rank=32, expert_alpha=32.0)\n    weight_path = os.path.join(args.checkpoint, \"model.safetensors\")\n    _sft.load_model(model, weight_path)\n    model.paligemma_with_expert.to_bfloat16_for_selected_params(\"bfloat16\")\n\n    asset_id = _detect_asset_id(args.checkpoint)\n    norm_stats = _checkpoints.load_norm_stats(\n        os.path.join(args.checkpoint, \"assets\"), asset_id\n    )\n    data_config = config.data.create(config.assets_dirs, config.model)\n\n    return _policy.Policy(\n        model,\n        transforms=[\n            *data_config.data_transforms.inputs,\n            _transforms.Normalize(norm_stats, use_quantiles=data_config.use_quantile_norm),\n            *data_config.model_transforms.inputs,\n        ],\n        output_transforms=[\n            *data_config.model_transforms.outputs,\n            _transforms.Unnormalize(norm_stats, use_quantiles=data_config.use_quantile_norm),\n            *data_config.data_transforms.outputs,\n        ],\n        metadata=config.policy_metadata,\n        is_pytorch=True,\n        pytorch_device=device,\n    )'''\n\n# Apply patches\n# 1. Insert _detect_asset_id before load_policy\nmarker = '\\ndef load_policy(args):'\nif marker not in content:\n    print(\"ERROR: Could not find load_policy marker\")\n    exit(1)\ncontent = content.replace(marker, new_code + 'def load_policy(args):', 1)\n\n# 2. Replace old load_policy with new\nif old_load not in content:\n    print(\"ERROR: Could not find old load_policy body\")\n    print(\"Searching for partial match...\")\n    idx = content.find('def load_policy(args):')\n    if idx >= 0:\n        print(f\"Found at position {idx}\")\n        print(repr(content[idx:idx+200]))\n    exit(1)\ncontent = content.replace(old_load, new_load, 1)\n\nwith open(filepath, 'w') as f:\n    f.write(content)\n\nprint(\"SUCCESS: Patch applied\")\nENDSCRIPT","account":"root"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":468,"cache_read_input_tokens":139537,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":468},"output_tokens":8,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"a07420f3-0e6b-4faa-8dd2-832b7168b989","uuid":"79ee1145-640f-431f-8185-58aab1b5b98d"}
